<?php
declare(strict_types=1);
namespace GeoFort\Services\Dashboard\Roster;
use ZipArchive;
use RuntimeException;

/** Native XLSX, consistent with the existing roster export; text is never a formula. */
final class StaffDeploymentXlsxWriter
{
    public function write(string $path,array $report):void
    {
        $summary=[['Medewerker','Type','Inzet uren','Definitief uren','In optie uren','Afgewezen uren','Zonder aanvraag uren','Scholen','Dagen','Begeleiding uren','Kok uren','Concept uren','Definitief rooster uren']];
        $modules=[['Medewerker','Module','Rol','Inzet uren','Afgewezen uren','Lesmomenten']];
        foreach($report['rows'] as $r){$s=$r['statuses'];$summary[]=[$r['name'],$r['employment']==='paid'?'Betaald':($r['employment']==='volunteer'?'Vrijwilliger':'Onbekend'),$r['minutes']/60,$s['Definitief']/60,$s['In optie']/60,$s['Afgewezen']/60,$s['Zonder aanvraag']/60,$r['schools'],$r['days'],$r['guideMinutes']/60,$r['cookMinutes']/60,$r['conceptMinutes']/60,$r['publishedMinutes']/60];foreach($r['modules'] as $m)$modules[]=[$r['name'],$m['module'],$m['role'],$m['minutes']/60,$m['rejectedMinutes']/60,$m['lessons']];}
        $detail=[['Medewerker','Datum','School','Aanvraagstatus','Roosterstatus','Module','Rol','Begin','Einde','Rooster ID']];
        foreach($report['entries'] as $e)$detail[]=[$e['name'],$e['date'],$e['school'],$e['status'],$e['rosterStatus']==='published'?'Definitief':'Concept',$e['moduleLabel'],$e['role'],$e['start'],$e['end'],$e['planId']];
        $notes=[['Berekening','Toelichting'],['Periode',$report['filters']['from'].' t/m '.$report['filters']['to']],['Filters',json_encode($report['filters'],JSON_UNESCAPED_UNICODE)],['Bron','Ingeplande les- en kokuren; geen registratie van werkelijk gewerkte uren.'],['Totaal','Zonder afgewezen aanvragen. Pauzes, aankomst en tussenuren tellen niet mee.'],['Overlap','Overlappende tijd per medewerker en dag telt eenmaal. Module-, rol- en statuskolommen kunnen overlappen; tel deze niet zelf op.'],['Scholen','Unieke combinatie van schoolnaam en plaats; alleen niet-afgewezen inzet.'],['Lesmomenten','Zelfde module, rol, medewerker, datum en tijd telt eenmaal, ook bij twee scholen.'],['Definitieve roosters','Vastgelegde snapshot; concepten gebruiken de huidige indeling.'],['Aanvraagstatus','Huidige status van de gekoppelde aanvraag; maatwerk zonder aanvraag staat apart.'],['Medewerkertype','Huidige personeelscatalogus; geen historische arbeidscontractregistratie.'],['Details','Bronregels kunnen gedeelde inzet bevatten; gebruik Overzicht voor ontdubbelde uren.']];
        $sheets=['Overzicht'=>$summary,'Modules'=>$modules,'Roosterregels'=>$detail,'Toelichting'=>$notes];
        if (isset($report['insights'])) {
            $insights=$report['insights']; $finance=$insights['finance'];
            $comparison=[['Type','Medewerkers','Uren','Medewerkerdagen','Gemiddelde uren','Korte inzet','Vrije lesminuten']];
            foreach($insights['groups'] as $g) $comparison[]=[$g['label'],$g['staff'],$g['minutes']/60,$g['staffDays'],$g['averageMinutes']/60,$g['shortVisits'],$g['gapMinutes']];
            $days=[['Medewerker','Datum','Lesuren','Vrije lesminuten','Kostenuren scenario','Kosten EUR','Tariefstatus']];
            foreach($insights['daily'] as $day) $days[]=[$day['name'],$day['date'],$day['minutes']/60,$day['gapMinutes'],$day['costMinutes']/60,$day['costCents']===null?'Onbekend':$day['costCents']/100,$day['costCents']===null?'Ontbrekend of dubbel':'Bekend'];
            $sheets['Vergelijking']=$comparison; $sheets['Medewerkerdagen']=$days;
            $sheets['Financieel scenario']=[['Onderdeel','Waarde'],['Kostenbasis',$report['filters']['costBasis']==='span'?'Eerste tot laatste les inclusief pauzes':'Les- en kokuren'],['Extra minuten per medewerkerdag',(int)$report['filters']['extraMinutes']],['Definitieve omzet excl btw EUR',$finance['revenue']['confirmedCents']/100],['Potentiële omzet excl btw EUR',$finance['revenue']['optionCents']/100],['Bekende personeelskosten EUR',$finance['knownCostCents']/100],['Ontbrekend tarief medewerkerdagen',$finance['unknownRateDays']],['Ontbrekende prijzen',$finance['revenue']['missing']],['Roosters zonder aanvraag',$finance['revenue']['unlinked']],['Omzet minus personeelskosten EUR',$finance['balanceCents']===null?'Onvolledig':$finance['balanceCents']/100],['Afbakening','Omzet van geselecteerde roosters, inclusief catering. Geen winst; andere kosten en niet-ingeroosterde inzet ontbreken.'],['Personeelsfilter',$finance['scopeComplete']?'Alle medewerkers':'Kosten van selectie; omzet niet verdeeld over medewerkers'],['Korte inzet','Maximaal 45 les- en kokminuten per medewerkerdag.'],['Vrije lesminuten','Tussen eigen lessen, waar een betrokken school wel lessen heeft.']];
        }
        $zip=new ZipArchive();if($zip->open($path,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Excel kon niet worden gemaakt.');
        try {
            $types='<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>';
            $work='<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>';$rels='<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">';$i=0;
            foreach($sheets as $name=>$rows){$i++;$types.='<Override PartName="/xl/worksheets/sheet'.$i.'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>';$work.='<sheet name="'.$name.'" sheetId="'.$i.'" r:id="r'.$i.'"/>';$rels.='<Relationship Id="r'.$i.'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'.$i.'.xml"/>';
                $xml='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="1" width="28" customWidth="1"/><col min="2" max="'.count($rows[0]).'" width="'.($name==='Toelichting'?100:24).'" customWidth="1"/></cols><sheetData>';
                foreach($rows as $r=>$row){$xml.='<row r="'.($r+1).'"'.($r===0?' ht="32" customHeight="1"':'').'>';foreach($row as $c=>$value){$col='';$n=$c+1;while($n>0){$n--;$col=chr(65+$n%26).$col;$n=intdiv($n,26);}$ref=$col.($r+1);$numeric=is_int($value)||is_float($value);$style=$r===0?1:($numeric?2:0);$xml.='<c r="'.$ref.'" s="'.$style.'"'.($numeric?'':' t="inlineStr"').'>'.($numeric?'<v>'.$value.'</v>':'<is><t xml:space="preserve">'.htmlspecialchars((string)$value,ENT_XML1|ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').'</t></is>').'</c>';}$xml.='</row>';}
                $xml.='</sheetData><autoFilter ref="A1:'.$col.count($rows).'"/></worksheet>';$zip->addFromString('xl/worksheets/sheet'.$i.'.xml',$xml);
            }
            $rels.='<Relationship Id="styles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>';
            $zip->addFromString('[Content_Types].xml',$types.'</Types>');$zip->addFromString('xl/workbook.xml',$work.'</sheets></workbook>');$zip->addFromString('xl/_rels/workbook.xml.rels',$rels);
            $zip->addFromString('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="book" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');
            $zip->addFromString('xl/styles.xml','<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF16376B"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="3"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"><alignment vertical="top" wrapText="1"/></xf><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFill="1" applyFont="1"><alignment wrapText="1"/></xf><xf numFmtId="2" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>');
        } finally {if (!$zip->close()) throw new RuntimeException('Excel kon niet worden opgeslagen.');}
    }
